pipeline:
pipeline {
  agent any

  environment {
    AWS_ACCESS_KEY_ID = 'AKIAEXAMPLE'
    AWS_SECRET_ACCESS_KEY = 'plain-text-secret'
  }

  stages {
    stage('Install') {
      steps {
        sh 'npm install'
      }
    }
    stage('Test') {
      steps {
        sh 'npm test || true'
      }
    }
    stage('Build') {
      steps {
        sh 'docker build -t registry.example.com/web:latest .'
        sh 'docker push registry.example.com/web:latest'
      }
    }
    stage('Deploy') {
      when { branch 'main' }
      steps {
        sh 'ssh deploy@prod.example.com docker pull registry.example.com/web:latest'
        sh 'ssh deploy@prod.example.com docker restart web'
      }
    }
  }
}
